-- SOURCE: 01_schema.sql
-- ==============================================================================
-- QuizNa Database Schema Migration 01: Core Tables, Constraints, and Indexes
-- ==============================================================================

-- UUIDv4 uses PostgreSQL 13+ core; no extension schema is required.

-- 1. Profiles Table (linked with Supabase Auth users)
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    email TEXT NOT NULL,
    full_name TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('teacher', 'student')),
    avatar_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Index for role lookup
CREATE INDEX IF NOT EXISTS idx_profiles_role ON public.profiles(role);

-- 2. Quizzes Table
CREATE TABLE IF NOT EXISTS public.quizzes (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    teacher_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    description TEXT,
    instructions TEXT,
    access_code VARCHAR(12) NOT NULL UNIQUE,
    time_limit_minutes INT NOT NULL DEFAULT 30 CHECK (time_limit_minutes > 0),
    max_attempts INT NOT NULL DEFAULT 1 CHECK (max_attempts > 0),
    randomize_questions BOOLEAN NOT NULL DEFAULT false,
    randomize_options BOOLEAN NOT NULL DEFAULT false,
    available_from TIMESTAMPTZ,
    available_until TIMESTAMPTZ,
    release_scores_immediately BOOLEAN NOT NULL DEFAULT false,
    release_answers_immediately BOOLEAN NOT NULL DEFAULT false,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
    version INT NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Indexes for quizzes
CREATE INDEX IF NOT EXISTS idx_quizzes_teacher ON public.quizzes(teacher_id);
CREATE INDEX IF NOT EXISTS idx_quizzes_access_code ON public.quizzes(access_code);
CREATE INDEX IF NOT EXISTS idx_quizzes_status ON public.quizzes(status);

-- 3. Quiz Versions Table (Freezes quiz structure when attempts are created)
CREATE TABLE IF NOT EXISTS public.quiz_versions (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    quiz_id UUID NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE,
    version_number INT NOT NULL,
    snapshot_data JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT uq_quiz_version UNIQUE(quiz_id, version_number)
);

CREATE INDEX IF NOT EXISTS idx_quiz_versions_quiz ON public.quiz_versions(quiz_id);

-- 4. Questions Table
CREATE TABLE IF NOT EXISTS public.questions (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    quiz_id UUID NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE,
    type TEXT NOT NULL CHECK (type IN ('mcq', 'true_false', 'short_answer', 'essay')),
    prompt TEXT NOT NULL,
    explanation TEXT,
    points NUMERIC(6, 2) NOT NULL DEFAULT 1.0 CHECK (points >= 0),
    order_index INT NOT NULL DEFAULT 0,
    options JSONB, -- Array of { id: string, text: string, is_correct?: boolean }
    correct_answer JSONB, -- Objective answer representation
    rubric TEXT, -- Guidance for manual grading of essays
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX IF NOT EXISTS idx_questions_quiz ON public.questions(quiz_id, order_index);

-- 5. Quiz Attempts Table
CREATE TABLE IF NOT EXISTS public.quiz_attempts (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    quiz_id UUID NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE,
    quiz_version_id UUID REFERENCES public.quiz_versions(id) ON DELETE SET NULL,
    student_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    attempt_number INT NOT NULL DEFAULT 1 CHECK (attempt_number > 0),
    status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'submitted', 'timed_out', 'terminated_violation')),
    started_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    deadline_at TIMESTAMPTZ NOT NULL,
    submitted_at TIMESTAMPTZ,
    score NUMERIC(6, 2),
    max_score NUMERIC(6, 2) NOT NULL DEFAULT 0,
    is_graded BOOLEAN NOT NULL DEFAULT false,
    warning_count INT NOT NULL DEFAULT 0 CHECK (warning_count >= 0 AND warning_count <= 3),
    question_order JSONB, -- Array of question IDs assigned to this student attempt
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT uq_student_attempt UNIQUE(quiz_id, student_id, attempt_number)
);

CREATE INDEX IF NOT EXISTS idx_attempts_quiz_student ON public.quiz_attempts(quiz_id, student_id);
CREATE INDEX IF NOT EXISTS idx_attempts_status ON public.quiz_attempts(status);
CREATE INDEX IF NOT EXISTS idx_attempts_deadline ON public.quiz_attempts(deadline_at);

-- 6. Attempt Answers Table
CREATE TABLE IF NOT EXISTS public.attempt_answers (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    attempt_id UUID NOT NULL REFERENCES public.quiz_attempts(id) ON DELETE CASCADE,
    question_id UUID NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE,
    answer JSONB, -- Value student provided
    score_awarded NUMERIC(6, 2),
    teacher_feedback TEXT,
    is_manually_graded BOOLEAN NOT NULL DEFAULT false,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT uq_attempt_question UNIQUE(attempt_id, question_id)
);

CREATE INDEX IF NOT EXISTS idx_answers_attempt ON public.attempt_answers(attempt_id);

-- 7. Quiz Incidents Table (Monitoring telemetry)
CREATE TABLE IF NOT EXISTS public.quiz_incidents (
    id UUID PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
    attempt_id UUID NOT NULL REFERENCES public.quiz_attempts(id) ON DELETE CASCADE,
    incident_type TEXT NOT NULL CHECK (incident_type IN ('tab_hidden', 'window_blur', 'fullscreen_exit')),
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    warning_number INT NOT NULL CHECK (warning_number BETWEEN 1 AND 3),
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE INDEX IF NOT EXISTS idx_incidents_attempt ON public.quiz_incidents(attempt_id, occurred_at);

-- Trigger for auto-updating updated_at timestamp
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = timezone('utc'::text, now());
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS tr_profiles_updated_at ON public.profiles;
CREATE TRIGGER tr_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS tr_quizzes_updated_at ON public.quizzes;
CREATE TRIGGER tr_quizzes_updated_at BEFORE UPDATE ON public.quizzes FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS tr_questions_updated_at ON public.questions;
CREATE TRIGGER tr_questions_updated_at BEFORE UPDATE ON public.questions FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS tr_quiz_attempts_updated_at ON public.quiz_attempts;
CREATE TRIGGER tr_quiz_attempts_updated_at BEFORE UPDATE ON public.quiz_attempts FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();

DROP TRIGGER IF EXISTS tr_attempt_answers_updated_at ON public.attempt_answers;
CREATE TRIGGER tr_attempt_answers_updated_at BEFORE UPDATE ON public.attempt_answers FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();


-- SOURCE: 02_rls.sql
-- ==============================================================================
-- QuizNa Database Schema Migration 02: Row Level Security (RLS) Policies
-- ==============================================================================

-- Enable RLS on all exposed tables
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quizzes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quiz_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quiz_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.attempt_answers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.quiz_incidents ENABLE ROW LEVEL SECURITY;

-- ------------------------------------------------------------------------------
-- Helper functions for RLS checks
-- ------------------------------------------------------------------------------

-- Get current user role from profiles
CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT AS $$
    SELECT role FROM public.profiles WHERE id = auth.uid();
$$ LANGUAGE sql STABLE SECURITY DEFINER;

-- Check if user is teacher of a quiz
CREATE OR REPLACE FUNCTION public.is_quiz_teacher(target_quiz_id UUID)
RETURNS BOOLEAN AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.quizzes
        WHERE id = target_quiz_id AND teacher_id = auth.uid()
    );
$$ LANGUAGE sql STABLE SECURITY DEFINER;

-- Check if user is teacher of an attempt
CREATE OR REPLACE FUNCTION public.is_attempt_teacher(target_attempt_id UUID)
RETURNS BOOLEAN AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.quiz_attempts qa
        JOIN public.quizzes q ON qa.quiz_id = q.id
        WHERE qa.id = target_attempt_id AND q.teacher_id = auth.uid()
    );
$$ LANGUAGE sql STABLE SECURITY DEFINER;

-- ------------------------------------------------------------------------------
-- 1. Profiles Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Users can view own profile"
    ON public.profiles FOR SELECT
    TO authenticated
    USING (id = auth.uid());

CREATE POLICY "Teachers can view profiles of students who attempted their quizzes"
    ON public.profiles FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            JOIN public.quizzes q ON qa.quiz_id = q.id
            WHERE q.teacher_id = auth.uid() AND qa.student_id = public.profiles.id
        )
    );

CREATE POLICY "Users can update own profile"
    ON public.profiles FOR UPDATE
    TO authenticated
    USING (id = auth.uid())
    WITH CHECK (id = auth.uid());

CREATE POLICY "Users can insert own profile"
    ON public.profiles FOR INSERT
    TO authenticated
    WITH CHECK (id = auth.uid());

-- ------------------------------------------------------------------------------
-- 2. Quizzes Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Teachers can manage own quizzes"
    ON public.quizzes FOR ALL
    TO authenticated
    USING (teacher_id = auth.uid())
    WITH CHECK (teacher_id = auth.uid());

CREATE POLICY "Students can view published quizzes"
    ON public.quizzes FOR SELECT
    TO authenticated
    USING (status = 'published');

-- ------------------------------------------------------------------------------
-- 3. Quiz Versions Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Teachers can manage versions of own quizzes"
    ON public.quiz_versions FOR ALL
    TO authenticated
    USING (public.is_quiz_teacher(quiz_id))
    WITH CHECK (public.is_quiz_teacher(quiz_id));

CREATE POLICY "Students can view version assigned to their attempt"
    ON public.quiz_versions FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.quiz_version_id = public.quiz_versions.id AND qa.student_id = auth.uid()
        )
    );

-- ------------------------------------------------------------------------------
-- 4. Questions Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Teachers can manage questions for own quizzes"
    ON public.questions FOR ALL
    TO authenticated
    USING (public.is_quiz_teacher(quiz_id))
    WITH CHECK (public.is_quiz_teacher(quiz_id));

CREATE POLICY "Students can view questions for quizzes they are actively taking"
    ON public.questions FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.quiz_id = public.questions.quiz_id AND qa.student_id = auth.uid()
        )
    );

-- ------------------------------------------------------------------------------
-- 5. Quiz Attempts Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Students can view own attempts"
    ON public.quiz_attempts FOR SELECT
    TO authenticated
    USING (student_id = auth.uid());

CREATE POLICY "Teachers can view attempts on own quizzes"
    ON public.quiz_attempts FOR SELECT
    TO authenticated
    USING (public.is_attempt_teacher(id));

CREATE POLICY "Students can create own attempts"
    ON public.quiz_attempts FOR INSERT
    TO authenticated
    WITH CHECK (student_id = auth.uid());

CREATE POLICY "Students can update own active attempts"
    ON public.quiz_attempts FOR UPDATE
    TO authenticated
    USING (student_id = auth.uid())
    WITH CHECK (student_id = auth.uid());

CREATE POLICY "Teachers can update attempts on their quizzes (e.g., grading)"
    ON public.quiz_attempts FOR UPDATE
    TO authenticated
    USING (public.is_attempt_teacher(id));

-- ------------------------------------------------------------------------------
-- 6. Attempt Answers Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Students can view answers to own attempts"
    ON public.attempt_answers FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.id = public.attempt_answers.attempt_id AND qa.student_id = auth.uid()
        )
    );

CREATE POLICY "Teachers can view and grade answers on own quizzes"
    ON public.attempt_answers FOR ALL
    TO authenticated
    USING (public.is_attempt_teacher(attempt_id));

CREATE POLICY "Students can insert or update answers for active in-progress attempts"
    ON public.attempt_answers FOR INSERT
    TO authenticated
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.id = public.attempt_answers.attempt_id
              AND qa.student_id = auth.uid()
              AND qa.status = 'in_progress'
              AND timezone('utc'::text, now()) <= qa.deadline_at
        )
    );

CREATE POLICY "Students can update answers for active in-progress attempts"
    ON public.attempt_answers FOR UPDATE
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.id = public.attempt_answers.attempt_id
              AND qa.student_id = auth.uid()
              AND qa.status = 'in_progress'
              AND timezone('utc'::text, now()) <= qa.deadline_at
        )
    );

-- ------------------------------------------------------------------------------
-- 7. Quiz Incidents Policies
-- ------------------------------------------------------------------------------
CREATE POLICY "Students can insert incidents for own attempts"
    ON public.quiz_incidents FOR INSERT
    TO authenticated
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.id = public.quiz_incidents.attempt_id AND qa.student_id = auth.uid()
        )
    );

CREATE POLICY "Students can view incidents for own attempts"
    ON public.quiz_incidents FOR SELECT
    TO authenticated
    USING (
        EXISTS (
            SELECT 1 FROM public.quiz_attempts qa
            WHERE qa.id = public.quiz_incidents.attempt_id AND qa.student_id = auth.uid()
        )
    );

CREATE POLICY "Teachers can view incidents for attempts on own quizzes"
    ON public.quiz_incidents FOR SELECT
    TO authenticated
    USING (public.is_attempt_teacher(attempt_id));


-- SOURCE: 04_attempt_integrity.sql
-- Apply after 01 and 02. Do NOT apply demo seed 03 to a production project.
-- All mutations go through the authenticated Nest API and service-role-only RPCs.

-- Remove permissive policies, including direct writes that bypass application rules.
DO $$ DECLARE p record; BEGIN
  FOR p IN SELECT tablename, policyname FROM pg_policies WHERE schemaname = 'public'
    AND tablename IN ('profiles','quizzes','questions','quiz_versions','quiz_attempts','attempt_answers','quiz_incidents')
  LOOP EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, p.tablename); END LOOP;
END $$;
REVOKE ALL ON public.profiles, public.quizzes, public.questions, public.quiz_versions,
  public.quiz_attempts, public.attempt_answers, public.quiz_incidents FROM anon, authenticated;
-- Teachers subscribe to protected tables; students get only sanitized REST responses.
GRANT SELECT ON public.profiles, public.quizzes, public.questions, public.quiz_versions,
  public.quiz_attempts, public.attempt_answers, public.quiz_incidents TO authenticated;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY teacher_students ON public.profiles FOR SELECT TO authenticated USING (
  EXISTS (SELECT 1 FROM public.quiz_attempts a JOIN public.quizzes q ON q.id=a.quiz_id
    WHERE a.student_id=profiles.id AND q.teacher_id=auth.uid()));
CREATE POLICY own_quizzes ON public.quizzes FOR SELECT TO authenticated USING (teacher_id=auth.uid());
CREATE POLICY own_questions ON public.questions FOR SELECT TO authenticated USING (public.is_quiz_teacher(quiz_id));
CREATE POLICY own_versions ON public.quiz_versions FOR SELECT TO authenticated USING (public.is_quiz_teacher(quiz_id));
CREATE POLICY teacher_attempts ON public.quiz_attempts FOR SELECT TO authenticated USING (public.is_attempt_teacher(id));
CREATE POLICY teacher_answers ON public.attempt_answers FOR SELECT TO authenticated USING (public.is_attempt_teacher(attempt_id));
CREATE POLICY own_incidents ON public.quiz_incidents FOR SELECT TO authenticated USING (
  public.is_attempt_teacher(attempt_id) OR EXISTS (SELECT 1 FROM public.quiz_attempts a WHERE a.id=attempt_id AND a.student_id=auth.uid()));
ALTER FUNCTION public.get_auth_role() SET search_path = '';
ALTER FUNCTION public.is_quiz_teacher(uuid) SET search_path = '';
ALTER FUNCTION public.is_attempt_teacher(uuid) SET search_path = '';

-- Students cannot choose a privileged role via signup metadata.
CREATE OR REPLACE FUNCTION public.quizna_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  INSERT INTO public.profiles(id,email,full_name,role)
  VALUES(NEW.id,NEW.email,coalesce(NEW.raw_user_meta_data->>'full_name',split_part(NEW.email,'@',1)),'student');
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS quizna_auth_profile ON auth.users;
CREATE TRIGGER quizna_auth_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.quizna_new_user();

-- Frozen questions may be removed from the editable draft without erasing saved answers.
ALTER TABLE public.attempt_answers DROP CONSTRAINT attempt_answers_question_id_fkey;
CREATE UNIQUE INDEX one_active_attempt ON public.quiz_attempts(quiz_id,student_id) WHERE status='in_progress';
CREATE INDEX due_attempts ON public.quiz_attempts(deadline_at) WHERE status='in_progress';
ALTER TABLE public.quiz_attempts ADD COLUMN auto_graded_at timestamptz;

-- Transaction-local finalization and grading; the same attempt row lock guards saves.
CREATE OR REPLACE FUNCTION public.quizna_finalize(p_id uuid,p_status text) RETURNS public.quiz_attempts
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE a public.quiz_attempts; q jsonb; ans jsonb; expected jsonb; correct boolean; pts numeric; total numeric:=0; graded boolean:=true; saved public.attempt_answers;
BEGIN
  SELECT * INTO a FROM public.quiz_attempts WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='QN404', MESSAGE='Attempt not found'; END IF;
  IF a.status <> 'in_progress' THEN RETURN a; END IF;
  IF p_status NOT IN ('submitted','timed_out','terminated_violation') THEN RAISE EXCEPTION 'Invalid status'; END IF;
  IF clock_timestamp() >= a.deadline_at THEN p_status:='timed_out'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.quiz_versions WHERE id=a.quiz_version_id) THEN RAISE EXCEPTION 'Quiz edition unavailable'; END IF;
  FOR q IN SELECT value FROM public.quiz_versions v, jsonb_array_elements(v.snapshot_data->'questions') WHERE v.id=a.quiz_version_id
  LOOP
    SELECT * INTO saved FROM public.attempt_answers WHERE attempt_id=a.id AND question_id=(q->>'id')::uuid;
    ans:=saved.answer; expected:=q->'correct_answer'; correct:=false;
    IF q->>'type'='essay' THEN
      -- Create a blank response so an unanswered essay can still be manually graded.
      INSERT INTO public.attempt_answers(attempt_id,question_id,answer) VALUES(a.id,(q->>'id')::uuid,null) ON CONFLICT DO NOTHING;
      IF saved.is_manually_graded THEN total:=total+coalesce(saved.score_awarded,0); ELSE graded:=false; END IF;
      CONTINUE;
    END IF;
    IF ans IS NOT NULL AND ans <> 'null'::jsonb THEN
      IF q->>'type'='short_answer' THEN
        IF jsonb_typeof(expected)='array' THEN
          SELECT EXISTS(SELECT 1 FROM jsonb_array_elements_text(expected) e WHERE lower(btrim(e))=lower(btrim(ans#>>'{}'))) INTO correct;
        ELSE correct:=lower(btrim(expected#>>'{}'))=lower(btrim(ans#>>'{}')); END IF;
      ELSIF q->>'type'='true_false' AND jsonb_typeof(expected)='boolean' THEN
        correct:=((ans#>>'{}') IN ('true','false','opt_true','opt_false')) AND (((ans#>>'{}') IN ('true','opt_true'))=(expected='true'::jsonb));
      ELSIF jsonb_typeof(expected)='array' THEN
        correct:=expected @> (CASE WHEN jsonb_typeof(ans)='array' THEN ans ELSE jsonb_build_array(ans) END)
          AND expected <@ (CASE WHEN jsonb_typeof(ans)='array' THEN ans ELSE jsonb_build_array(ans) END);
      ELSIF q->>'type'='true_false' THEN correct:=lower(ans#>>'{}')=lower(expected#>>'{}');
      ELSE correct:=btrim(ans#>>'{}')=btrim(expected#>>'{}'); END IF;
    END IF;
    pts:=CASE WHEN coalesce(correct,false) THEN (q->>'points')::numeric ELSE 0 END;
    total:=total+pts;
    INSERT INTO public.attempt_answers(attempt_id,question_id,answer,score_awarded,is_manually_graded)
    VALUES(a.id,(q->>'id')::uuid,ans,pts,true)
    ON CONFLICT(attempt_id,question_id) DO UPDATE SET score_awarded=excluded.score_awarded,is_manually_graded=true;
  END LOOP;
  UPDATE public.quiz_attempts SET status=p_status,submitted_at=clock_timestamp(),score=total,is_graded=graded,auto_graded_at=clock_timestamp() WHERE id=a.id RETURNING * INTO a;
  RETURN a;
END $$;

CREATE OR REPLACE FUNCTION public.quizna_attempt_command(p_action text,p_actor uuid,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE a public.quiz_attempts; quiz public.quizzes; v public.quiz_versions; answer_row public.attempt_answers; incident public.quiz_incidents;
  q jsonb; ordered jsonb; deadline timestamptz; n integer; last_time timestamptz; t timestamptz; final_status text; action_taken text;
BEGIN
  IF p_action='expire' THEN
    FOR a IN SELECT * FROM public.quiz_attempts WHERE status='in_progress' AND deadline_at<=clock_timestamp() LIMIT 100 FOR UPDATE SKIP LOCKED
    LOOP PERFORM public.quizna_finalize(a.id,'timed_out'); END LOOP;
    RETURN '{}'::jsonb;
  END IF;
  IF p_action='publish' THEN
    SELECT * INTO quiz FROM public.quizzes WHERE id=(p_payload->>'quiz_id')::uuid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='QN404'; END IF;
    IF quiz.teacher_id IS DISTINCT FROM p_actor THEN RAISE EXCEPTION USING ERRCODE='QN403'; END IF;
    SELECT jsonb_agg(to_jsonb(question_row) ORDER BY order_index) INTO ordered FROM public.questions question_row WHERE question_row.quiz_id=quiz.id;
    IF ordered IS NULL THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    SELECT greatest(quiz.version,coalesce(max(version_number),0))+1 INTO n FROM public.quiz_versions WHERE quiz_id=quiz.id;
    INSERT INTO public.quiz_versions(quiz_id,version_number,snapshot_data) VALUES(quiz.id,n,
      jsonb_build_object('title',quiz.title,'instructions',quiz.instructions,'time_limit_minutes',quiz.time_limit_minutes,
        'max_attempts',quiz.max_attempts,'randomize_questions',quiz.randomize_questions,'randomize_options',quiz.randomize_options,'questions',ordered));
    UPDATE public.quizzes SET status='published',version=n WHERE id=quiz.id RETURNING * INTO quiz;
    RETURN to_jsonb(quiz);
  END IF;
  IF p_action='grade' THEN
    SELECT * INTO answer_row FROM public.attempt_answers WHERE id=(p_payload->>'answer_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='QN404'; END IF;
    SELECT * INTO a FROM public.quiz_attempts WHERE id=answer_row.attempt_id FOR UPDATE;
    IF NOT EXISTS(SELECT 1 FROM public.quizzes WHERE id=a.quiz_id AND teacher_id=p_actor) THEN RAISE EXCEPTION USING ERRCODE='QN403'; END IF;
    IF a.status='in_progress' THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    SELECT value INTO q FROM public.quiz_versions version_row,jsonb_array_elements(version_row.snapshot_data->'questions') WHERE version_row.id=a.quiz_version_id AND value->>'id'=answer_row.question_id::text;
    IF q IS NULL OR (p_payload->>'score')::numeric<0 OR (p_payload->>'score')::numeric>(q->>'points')::numeric THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    UPDATE public.attempt_answers SET score_awarded=(p_payload->>'score')::numeric,teacher_feedback=p_payload->>'feedback',is_manually_graded=true WHERE id=answer_row.id RETURNING * INTO answer_row;
    UPDATE public.quiz_attempts SET score=(SELECT coalesce(sum(score_awarded),0) FROM public.attempt_answers WHERE attempt_id=a.id),
      is_graded=NOT EXISTS(SELECT 1 FROM public.quiz_versions version_row,jsonb_array_elements(version_row.snapshot_data->'questions') item
        WHERE version_row.id=a.quiz_version_id AND item->>'type'='essay' AND NOT EXISTS(
          SELECT 1 FROM public.attempt_answers ans WHERE ans.attempt_id=a.id AND ans.question_id=(item->>'id')::uuid AND ans.is_manually_graded))
      WHERE id=a.id;
    RETURN to_jsonb(answer_row);
  END IF;
  IF p_action='start' THEN
    IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor AND role='student') THEN RAISE EXCEPTION USING ERRCODE='QN403'; END IF;
    SELECT * INTO quiz FROM public.quizzes WHERE access_code=upper(btrim(p_payload->>'access_code'));
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='QN404'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(quiz.id::text||p_actor::text,0));
    -- Resume before checking availability: editing/closing a quiz cannot invalidate an active attempt.
    SELECT * INTO a FROM public.quiz_attempts WHERE quiz_id=quiz.id AND student_id=p_actor AND status='in_progress' FOR UPDATE;
    IF FOUND AND a.deadline_at>clock_timestamp() THEN RETURN jsonb_build_object('attempt',to_jsonb(a),'isResumed',true); END IF;
    IF a.id IS NOT NULL THEN
      a:=public.quizna_finalize(a.id,'timed_out');
      RETURN jsonb_build_object('attempt',to_jsonb(a),'isResumed',true);
    END IF;
    IF quiz.status<>'published' OR quiz.available_from>clock_timestamp() OR quiz.available_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    SELECT * INTO v FROM public.quiz_versions WHERE quiz_id=quiz.id AND version_number=quiz.version;
    IF NOT FOUND OR jsonb_array_length(v.snapshot_data->'questions')=0 THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    SELECT count(*) INTO n FROM public.quiz_attempts WHERE quiz_id=quiz.id AND student_id=p_actor;
    IF n>=quiz.max_attempts THEN RAISE EXCEPTION USING ERRCODE='QN409'; END IF;
    SELECT jsonb_agg(value->>'id' ORDER BY CASE WHEN (v.snapshot_data->>'randomize_questions')::boolean THEN random() ELSE ord::float8 END)
      INTO ordered FROM jsonb_array_elements(v.snapshot_data->'questions') WITH ORDINALITY AS e(value,ord);
    deadline:=least(clock_timestamp()+make_interval(mins=>(v.snapshot_data->>'time_limit_minutes')::int),coalesce(quiz.available_until,'infinity'::timestamptz));
    INSERT INTO public.quiz_attempts(quiz_id,quiz_version_id,student_id,attempt_number,deadline_at,max_score,question_order)
    VALUES(quiz.id,v.id,p_actor,n+1,deadline,(SELECT sum((value->>'points')::numeric) FROM jsonb_array_elements(v.snapshot_data->'questions')),ordered) RETURNING * INTO a;
    RETURN jsonb_build_object('attempt',to_jsonb(a),'isResumed',false);
  END IF;

  SELECT * INTO a FROM public.quiz_attempts WHERE id=(p_payload->>'attempt_id')::uuid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='QN404'; END IF;
  IF p_action IN ('save','incident') AND a.student_id IS DISTINCT FROM p_actor THEN RAISE EXCEPTION USING ERRCODE='QN403'; END IF;
  IF p_action='finalize' THEN
    RETURN to_jsonb(public.quizna_finalize(a.id,p_payload->>'status'));
  END IF;
  IF p_action='pardon' THEN
    IF NOT EXISTS(SELECT 1 FROM public.quizzes WHERE id=a.quiz_id AND teacher_id=p_actor) THEN RAISE EXCEPTION USING ERRCODE='QN403'; END IF;
    IF a.status<>'in_progress' OR clock_timestamp()>=a.deadline_at THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    INSERT INTO public.quiz_incidents(attempt_id,incident_type,warning_number,details) VALUES(a.id,'window_blur',greatest(1,a.warning_count),jsonb_build_object('action','teacher_pardon','teacher_id',p_actor));
    UPDATE public.quiz_attempts SET warning_count=greatest(0,warning_count-1) WHERE id=a.id RETURNING * INTO a;
    RETURN to_jsonb(a);
  END IF;
  IF clock_timestamp()>=a.deadline_at AND a.status='in_progress' THEN a:=public.quizna_finalize(a.id,'timed_out'); END IF;
  IF p_action='save' THEN
    -- Return a committed closed response instead of raising, so expiry is not rolled back.
    IF a.status<>'in_progress' THEN RETURN jsonb_build_object('status','closed','attempt_id',a.id,'attempt_status',a.status); END IF;
    SELECT value INTO q FROM public.quiz_versions version_row,jsonb_array_elements(version_row.snapshot_data->'questions') WHERE version_row.id=a.quiz_version_id AND value->>'id'=p_payload->>'question_id';
    IF q IS NULL THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    IF jsonb_typeof(p_payload->'answer') NOT IN ('string','null') THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    IF q->>'type' IN ('mcq','true_false') AND p_payload->'answer'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q->'options') option_row WHERE option_row->>'id'=p_payload->>'answer') THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    IF length(p_payload->>'answer')>50000 THEN RAISE EXCEPTION USING ERRCODE='QN400'; END IF;
    INSERT INTO public.attempt_answers(attempt_id,question_id,answer) VALUES(a.id,(p_payload->>'question_id')::uuid,p_payload->'answer')
    ON CONFLICT(attempt_id,question_id) DO UPDATE SET answer=excluded.answer RETURNING * INTO answer_row;
    RETURN jsonb_build_object('status','saved','answer',to_jsonb(answer_row));
  END IF;
  IF p_action='incident' THEN
    t:=clock_timestamp();
    SELECT max(occurred_at) INTO last_time FROM public.quiz_incidents WHERE attempt_id=a.id;
    IF a.status<>'in_progress' OR t-a.started_at<interval '3 seconds' OR t-last_time<interval '2 seconds' THEN
      RETURN jsonb_build_object('deduplicated',true,'warning_number',a.warning_count,'action_taken','none');
    END IF;
    n:=least(3,a.warning_count+1);
    INSERT INTO public.quiz_incidents(attempt_id,incident_type,warning_number,details,occurred_at) VALUES(a.id,p_payload->>'incident_type',n,coalesce(p_payload->'details','{}'::jsonb),t) RETURNING * INTO incident;
    UPDATE public.quiz_attempts SET warning_count=n WHERE id=a.id RETURNING * INTO a;
    action_taken:=CASE n WHEN 1 THEN 'first_warning' WHEN 2 THEN 'final_warning' ELSE 'terminated' END;
    IF n=3 THEN a:=public.quizna_finalize(a.id,'terminated_violation'); END IF;
    RETURN jsonb_build_object('deduplicated',false,'warning_number',n,'action_taken',action_taken,'incident',to_jsonb(incident));
  END IF;
  RAISE EXCEPTION 'Unknown command';
END $$;

REVOKE ALL ON FUNCTION public.quizna_new_user(),public.quizna_finalize(uuid,text),public.quizna_attempt_command(text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.quizna_finalize(uuid,text),public.quizna_attempt_command(text,uuid,jsonb) TO service_role;
-- Teacher dashboards may subscribe to these RLS-protected tables.
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['quiz_attempts','attempt_answers','quiz_incidents'] LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t);
    END IF;
  END LOOP;
END $$;

