CREATE TABLE IF NOT EXISTS public.quiz_sections (
 id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),
 quiz_id uuid NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE,
